/bin/bash -lc "node <<'NODE'
const base = 'http://localhost:8080';
let token = null;
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function getToken() {
  for (;;) {
    const res = await fetch(base + '/token', {method:'POST'});
    if (res.ok) { token = (await res.json()).token; return; }
    const ra = res.headers.get('retry-after');
    await sleep((ra ? Number(ra)*1000 : 1000));
  }
}
async function api(path) {
  for (;;) {
    if ("'!token) await getToken();
    let res;
    try { res = await fetch(base + path, {headers:{Authorization:`Bearer ${token}`}}); }
    catch { await sleep(1000); continue; }
    if (res.ok) return await res.json();
    if (res.status === 401) { token = null; continue; }
    if (res.status === 429 || res.status >= 500) {
      const ra = res.headers.get('"'retry-after');
      await sleep((ra ? Number(ra)*1000 : 1000));
      continue;
    }
    throw new Error("'`${path}: HTTP ${res.status} ${await res.text()}`);
  }
}
(async () => {
  const unique = new Map(); let duplicates=0, pages=0;
  for (let page=1;;page++) {
    const data=await api(`/orders?page=${page}`); pages++;
    for (const order of data.items) {
      if (unique.has(order.id)) duplicates++; else unique.set(order.id, order);
    }
    if (!data.next) break;
  }
  const customers=new Map();
  for (const order of unique.values()) {
    if (!customers.has(order.customer_id)) customers.set(order.customer_id, await api(`/customers/${encodeURIComponent(order.customer_id)}`));
  }
  const regions={north:0,south:0,east:0,west:0}; let count=0;
  const start=Date.parse('"'2025-03-01T00:00:00.000Z'), end=Date.parse('2025-06-01T00:00:00.000Z');
  for (const o of unique.values()) {
    if (o.status "'!== '"'shipped') continue;
    const t=Date.parse(o.placed_at);
    if ("'!(t >= start && t < end)) continue;
    const c=customers.get(o.customer_id);
    const discounted=Math.floor((o.amount_cents*(100-c.discount_pct)+50)/100);
    regions[c.region]+=discounted; count++;
  }
  const total=Object.values(regions).reduce((a,b)=>a+b,0);
  console.log(JSON.stringify({total_cents:total,order_count:count,duplicates_skipped:duplicates,by_region:regions,pages,unique_orders:unique.size,customers:customers.size},null,2));
})().catch(e=>{console.error(e.stack);process.exit(1)});
NODE'

